#include "creator_ai_page.hpp"
#include "request_authorization_widget.hpp"
#include "creator_ai_model.hpp"
#include "ai_settings_store.hpp"
#include "research_runs_model.hpp"
#include <QtWidgets>
namespace {
QString pretty(const QJsonObject&o){return QString::fromUtf8(QJsonDocument(o).toJson());}
QString candidateReview(const QJsonObject&candidate){
 auto analysis=candidate["analysis"].toObject();auto edges=analysis["relations"].toArray();
 QString text="作者观点候选 · "+candidate["provenance"].toString()+" · 尚未保存\n仅依据本机文稿，不代表外部核验。\n\n摘要\n"+analysis["summary"].toString()+"\n\n关系与原文依据（"+QString::number(edges.size())+" 条）\n";
 if(edges.isEmpty())text+="全部分块已返回，本篇没有明确关系。\n";
 for(auto value:edges){auto e=value.toObject();text+=e["from"].toString()+" → "+e["to"].toString()+" · "+e["relation"].toString()+" · "+(e["polarity"]=="contradicts"?"相反观点":"支持观点")+"\n主题："+e["topic"].toString()+"\n原文："+e["quote"].toString()+"\n疑点："+e["uncertainty"].toString()+"\n\n";}
 return text+"\n完整候选记录（含全文、来源和逐块身份，原样保留）\n"+pretty(candidate);
}
}
CreatorAiPage::CreatorAiPage(std::shared_ptr<BusinessStore>s,std::function<void()> back,QWidget*parent,QNetworkAccessManager*fake):QWidget(parent),store(std::move(s)),backCallback(std::move(back)){
 setObjectName("creatorAiPage");auto layout=new QVBoxLayout(this);auto bar=new QHBoxLayout;layout->addLayout(bar);
 auto add=[&](QString label,QString name,std::function<void()> fn){auto*b=new QPushButton(label);b->setObjectName(name);bar->addWidget(b);connect(b,&QPushButton::clicked,this,[this,b,fn]{if(allowed(b))guard(fn);});return b;};
 add("返回作者关系","creatorAiBack",[this]{cancel();if(backCallback)backCallback();});add("冻结文稿 / 预览全部分块","creatorAiPrepare",[this]{prepare();});
 add("导入逐块返回文件","creatorAiImport",[this]{auto ticket=epoch;auto file=QFileDialog::getOpenFileName(this,"选择逐块返回文件",{},"JSON 文件 (*.json)");if(ticket!=epoch||!allowed()||file.isEmpty())return;importFile(file);});
 validateButton=add("验证所有块 / 生成候选","creatorAiValidate",[this]{validate();});confirmButton=add("明确追加本次观点历史","creatorAiConfirm",[this]{confirm();});add("取消待确认","creatorAiCancel",[this]{cancel();status->setText("已取消后续执行和待确认资格；已发生的请求记录保留。");});
 auto executionBar=new QHBoxLayout;layout->addLayout(executionBar);auto preview=new QPushButton("预览全部执行请求");preview->setObjectName("creatorAiExecutionPreview");executionBar->addWidget(preview);
 executeConsent=new QCheckBox("已审阅全部外发内容，同意本次逐块执行及提供方计费");executeConsent->setObjectName("creatorAiExecutionConsent");executionBar->addWidget(executeConsent,1);
 executeButton=new QPushButton("明确开始逐块执行");executeButton->setObjectName("creatorAiExecute");executeButton->setEnabled(false);executionBar->addWidget(executeButton);
 connect(preview,&QPushButton::clicked,this,[this,preview]{if(allowed(preview))guard([this]{previewExecution();});});
 connect(executeConsent,&QCheckBox::toggled,this,[this](bool checked){executeButton->setEnabled(checked&&execution&&execution->ready()&&(!authority||authority->ready())&&execution->snapshot()["status"]=="prepared");});
 connect(executeButton,&QPushButton::clicked,this,[this]{if(allowed(executeButton))guard([this]{startExecution();});});
 status=new QLabel;status->setObjectName("creatorAiStatus");status->setWordWrap(true);layout->addWidget(status);tabs=new QTabWidget;tabs->setObjectName("creatorAiTabs");layout->addWidget(tabs,1);
 auto read=[&](QString name){auto*t=new QPlainTextEdit;t->setObjectName(name);t->setReadOnly(true);return t;};
 auto input=new QWidget;auto il=new QVBoxLayout(input);source=read("creatorAiSource");il->addWidget(source,1);auto split=new QSplitter;il->addWidget(split,2);chunks=new QListWidget;chunks->setObjectName("creatorAiChunks");split->addWidget(chunks);chunkBody=read("creatorAiChunkBody");split->addWidget(chunkBody);split->setSizes({280,720});tabs->addTab(input,"完整来源 / 全部分块");
 returnBody=read("creatorAiReturn");tabs->addTab(returnBody,"原始逐块返回");candidateBody=read("creatorAiCandidate");tabs->addTab(candidateBody,"完整候选 / 提交结果");auto past=new QSplitter;histories=new QListWidget;histories->setObjectName("creatorAiHistory");past->addWidget(histories);historyBody=read("creatorAiHistoryBody");past->addWidget(historyBody);past->setSizes({280,720});tabs->addTab(past,"既有完整观点历史");
 requestBody=read("creatorAiRequests");tabs->addTab(requestBody,"全部执行请求 / 过程证据");
 execution=new creatorExecution::Session([this]{return current();},[this]{return allowed();},this,fake);execution->changed=[this]{executionChanged();};
 authority=new RequestAuthorizationWidget([this]{return allowed();},this);layout->insertWidget(2,authority);execution->configure({[this](const aiKnowledge::Prepared&r){return authority->authorize(r);},[this]{return authority->acquire();}});authority->changed=[this]{executeButton->setEnabled(executeConsent->isChecked()&&authority->ready()&&execution->ready()&&execution->snapshot()["status"]=="prepared");};authority->expired=[this]{cancel();};
 connect(qApp,&QGuiApplication::applicationStateChanged,this,[this](Qt::ApplicationState s){if(s!=Qt::ApplicationActive)cancel();});
 connect(chunks,&QListWidget::currentRowChanged,this,[this](int i){if(!allowed(chunks)||i<0)return;guard([this,i]{auto blocks=manifest["blocks"].toArray();business::require(i<blocks.size(),"分块选择已变化");chunkBody->setPlainText(pretty(blocks[i].toObject())+"\n\n完整提示词（只读，尚未发送）\n"+creatorAi::prompt(manifest,i));});});
 connect(histories,&QListWidget::currentRowChanged,this,[this](int i){if(!allowed(histories)||i<0)return;historyBody->setPlainText(pretty(histories->item(i)->data(Qt::UserRole).toJsonObject()));});
 connect(qApp,&QGuiApplication::applicationStateChanged,this,[this](Qt::ApplicationState s){if(s!=Qt::ApplicationActive)cancel();});confirmButton->setEnabled(false);validateButton->setEnabled(false);
}
CreatorAiPage::~CreatorAiPage(){execution->changed={};close();}
bool CreatorAiPage::allowed(const QWidget*origin)const{return !closed&&isVisible()&&isEnabled()&&!window()->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive&&(!origin||(origin->isVisible()&&origin->isEnabled()));}
void CreatorAiPage::guard(const std::function<void()>&fn){try{fn();}catch(const std::exception&e){cancel();status->setText("未形成可提交结果："+QString::fromUtf8(e.what())+"；原文稿与历史保留。");}}
QJsonObject CreatorAiPage::current()const{auto row=BusinessStore::readRecord(store->filePath(),"collections",expected["id"].toString());business::require(!row.isEmpty(),"原文稿已不存在");return row;}
void CreatorAiPage::open(const QJsonObject&row){business::require(!closed,"页面已关闭");cancel();expected=row;manifest={};returned={};source->setPlainText("完整选中文稿（含原来源字段，不推断作者或日期）\n"+pretty(row));chunks->clear();chunkBody->clear();returnBody->clear();candidateBody->clear();validateButton->setEnabled(false);tabs->setCurrentIndex(0);history();status->setText("尚未执行；无本次授权与凭据。先明确冻结完整文稿，再导入并验证返回文件；执行须另行预览全部请求，并具备本次授权与短期凭据。");}
void CreatorAiPage::prepare(){cancel();business::require(researchRuns::canonical(current())==researchRuns::canonical(expected),"完整文稿记录已变化，请返回重读");manifest=creatorAi::plan(expected);returned={};returnBody->clear();candidateBody->clear();validateButton->setEnabled(false);chunks->clear();for(auto v:manifest["blocks"].toArray()){auto b=v.toObject();chunks->addItem(QString("块 %1 · UTF-16 [%2, %3)\n%4").arg(b["index"].toInt()+1).arg(b["start"].toInt()).arg(b["end"].toInt()).arg(b["blockHash"].toString()));}source->setPlainText("完整文稿与分块计划（尚未发送）\n"+pretty(manifest));tabs->setCurrentIndex(0);chunks->setCurrentRow(0);status->setText(QString("已冻结 %1 块；全部正文与来源版本均可读。未执行在线分析。").arg(chunks->count()));}
void CreatorAiPage::importFile(const QString&path){if(!allowed())return;guard([&]{cancel();returned={};validateButton->setEnabled(false);business::require(!manifest.isEmpty(),"先冻结文稿并查看全部分块");QFile f(path);business::require(f.open(QIODevice::ReadOnly)&&f.size()>0&&f.size()<=8*1024*1024,"返回文件不可读或超过8MiB，未截断");auto bytes=f.read(8*1024*1024+1);business::require(f.atEnd()&&bytes.size()<=8*1024*1024,"返回文件读取不完整或过大");auto parsed=creatorAi::parseObject(bytes);returnBody->setPlainText(QString::fromUtf8(bytes));business::require(parsed.keys()==QStringList{"planHash","responses","schema"}&&parsed["schema"]=="native-creator-ai-return/v1"&&parsed["planHash"]==manifest["planHash"]&&parsed["responses"].isArray(),"返回文件结构或计划身份不匹配");for(auto v:parsed["responses"].toArray())business::require(v.isObject()&&v.toObject()["provenance"]=="manual-import","文件仅接受manual-import；不能导入声明在线或冒充受控假回包");returned=parsed;validateButton->setEnabled(true);tabs->setCurrentIndex(1);status->setText("已读入人工导入文件，尚未完成验证；不代表真实在线执行。");});}
void CreatorAiPage::validate(){cancel();business::require(!manifest.isEmpty()&&!returned.isEmpty(),"先冻结文稿并导入返回文件");business::require(researchRuns::canonical(current())==researchRuns::canonical(expected),"完整来源已变化，请返回重读");auto responses=returned["responses"].toArray();business::require(!responses.isEmpty(),"缺少逐块返回");candidate=creatorAi::aggregate(manifest,responses,QUuid::createUuid().toString(QUuid::WithoutBraces),responses.first().toObject()["model"].toString(),QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));candidateBody->setPlainText(candidateReview(candidate));confirmButton->setEnabled(true);tabs->setCurrentIndex(2);status->setText(candidate["status"]=="complete_empty"?"所有块验证完成：无明确关系。人工导入，需明确确认才追加历史。":"所有块验证完成：仅作者观点候选，人工导入；需明确确认才追加历史。");}
void CreatorAiPage::confirm(){business::require(!candidate.isEmpty(),"没有待确认候选");auto ticket=epoch;auto held=candidate;auto cancelled=[this,ticket]{return ticket!=epoch||!allowed();};auto receipt=executionReceipt;auto result=receipt?store->saveCreatorAiExecution(expected,held,*receipt,cancelled):store->saveCreatorAiAnalysis(expected,held,cancelled);cancel();candidateBody->setPlainText("已追加保存的完整记录\n"+pretty(result));status->setText("已追加保存观点历史；原文、人工关系和旧版本保留。来源："+held["provenance"].toString());try{history();}catch(const std::exception&){status->setText(status->text()+" 历史列表刷新失败，请返回重读；本次提交已经成功。");}}
void CreatorAiPage::history(){histories->clear();historyBody->clear();auto row=current();for(auto v:row["creatorAnalyses"].toArray()){auto a=v.toObject();auto*i=new QListWidgetItem(a["analyzedAt"].toString()+" · "+a["model"].toString()+" · "+a["provenance"].toString(a["creatorAi"].toObject()["provenance"].toString("人工/旧版本")),histories);i->setData(Qt::UserRole,a);}}
void CreatorAiPage::cancel(){if(authority)authority->clear();++epoch;if(execution)execution->cancel();executionReceipt.reset();if(executeConsent)executeConsent->setChecked(false);if(executeButton)executeButton->setEnabled(false);candidate={};if(confirmButton)confirmButton->setEnabled(false);}
void CreatorAiPage::close(){if(closed)return;cancel();closed=true;setEnabled(false);}
void CreatorAiPage::hideEvent(QHideEvent*e){cancel();QWidget::hideEvent(e);}

void CreatorAiPage::configureExecution(creatorExecution::Host host){cancel();delete authority;authority=nullptr;execution->configure(std::move(host));}
void CreatorAiPage::previewExecution(){prepare();auto prefs=aiSettings::Store(QFileInfo(store->filePath()).absolutePath()+"/ai-settings-v1.sqlite").read()["preferences"].toObject();auto snapshot=execution->prepare(expected,prefs);if(authority)authority->bind(execution->preparedRequests());requestBody->setPlainText(pretty(snapshot));tabs->setCurrentWidget(requestBody);status->setText(execution->ready()?"全部请求可逐项阅读；尚未发送。审阅并勾选后可明确开始。":"全部请求可逐项阅读；本次授权或短期凭据未连接，执行不可用。");}
void CreatorAiPage::startExecution(){business::require(executeConsent->isChecked()&&execution->ready()&&(!authority||authority->ready()),"先审阅并确认全部请求；本次授权和凭据必须可用");candidate={};executionReceipt.reset();confirmButton->setEnabled(false);validateButton->setEnabled(false);returned={};returnBody->clear();execution->start();}
void CreatorAiPage::executionChanged(){if(!allowed())return;auto snapshot=execution->snapshot();auto state=snapshot["status"].toString();requestBody->setPlainText(pretty(snapshot));executeButton->setEnabled(state=="prepared"&&execution->ready()&&(!authority||authority->ready())&&executeConsent->isChecked());if(state=="running"){status->setText(QString("正在逐块执行 %1 / %2；可随时取消，尚未保存。").arg(snapshot["completed"].toInt()).arg(snapshot["total"].toInt()));return;}if((state=="completed"||state=="failed"||state=="blocked"||state=="timed-out")&&authority)authority->clear();if(state=="completed"){auto receipt=execution->receipt();if(!receipt||!receipt->valid())return;candidate=snapshot["candidate"].toObject();executionReceipt=receipt;candidateBody->setPlainText(candidateReview(candidate));returnBody->setPlainText(pretty(QJsonObject{{"responses",snapshot["responses"]},{"attempts",snapshot["attempts"]}}));confirmButton->setEnabled(true);tabs->setCurrentIndex(2);status->setText("全部块完成并校验；来源："+candidate["provenance"].toString()+"。请审阅完整候选后明确追加历史。");}else if(state=="failed"||state=="blocked"||state=="timed-out"){candidate={};executionReceipt.reset();confirmButton->setEnabled(false);status->setText("执行未形成候选："+state+" · "+snapshot["error"].toString()+"；过程证据可读，未保存。");}}
